#!/usr/bin/env bash
# Fetch open CodeRabbit review threads on PR 192.
# Thread metadata via GraphQL; bodies via REST (GraphQL bodies carry unescaped
# control chars that break jq).
set -uo pipefail
owner=SMK1085; repo=paigasus-helikon; pr=192

gh api graphql -F owner="$owner" -F repo="$repo" -F pr="$pr" -f query='
  query($owner:String!,$repo:String!,$pr:Int!){
    repository(owner:$owner,name:$repo){
      pullRequest(number:$pr){
        reviewThreads(first:100){
          nodes{
            id isResolved isOutdated
            comments(first:1){ nodes{ databaseId path line author{ login } } }
          }
        }
      }
    }
  }' --jq '
  .data.repository.pullRequest.reviewThreads.nodes[]
  | select(.isResolved == false and .isOutdated == false)
  | select(.comments.nodes[0].author.login | test("coderabbit"; "i"))
  | "\(.id)\t\(.comments.nodes[0].databaseId)\t\(.comments.nodes[0].path):\(.comments.nodes[0].line)"'

